mapper.update:
update claim set is_check=#{claim.is_check}
             ,senderId=#{claim.senderId}
             ,receiverId=#{claim.receiverId}
             ,sender=#{claim.sender}
             ,receiver=#{claim.receiver}
             ,reason=#{claim.reason}
             ,c_id=#{claim.c_id}
             where id=#{claim.id}

mapper.select:
select claim.*,found.name,found.time,found.location,found.pathName
from claim,found
where claim.c_id=#{c_id} and claim.senderId=#{senderId}
                      and claim.receiverId=#{receiverId}
                      and found.id=#{c_id}
